async function watch(client,name,expectedActive){await expect(client.page.locator('[data-puzzle-roster]')).toContainText('You are watching');await expect(client.page.locator('[data-puzzle-roster]')).toContainText(expectedActive+' / 6 active');await expect(action(client,'join')).toBeVisible();await expect.poll(()=>client.live?.roster?.selfParticipationId??null).toBe(null);assert.ok(!client.live.roster.memberIds.includes(client.selfId));const piece=art.pieces.find(item=>!client.live.puzzle.current?.placements.some(placement=>placement.pieceId===item.id));if(piece){await expect(client.page.locator('[data-puzzle-piece="'+piece.id+'"]')).toHaveAttribute('aria-disabled','true');await expect(client.page.locator('[data-puzzle-destination="'+piece.destination+'"]')).toHaveAttribute('aria-disabled','true');}const snapshot=await readDurable(client);assert.equal(snapshot.puzzle.current?.placements.length??0,count);await verifyAuthority(client,name,snapshot,{active:expectedActive,joined:false});result.observations.push({kind:'negative-watch-authority',name,client:client.index,selfId:client.selfId,count,active:client.live.roster.memberIds,selfParticipationId:client.live.roster.selfParticipationId,actorCounts:authorCounts(snapshot),at:new Date().toISOString()});await surface(client,name);}
async function joinPicture(client,expectedActive){await action(client,'join')[client.touch?'tap':'click']();await expect(client.page.locator('[data-puzzle-roster]')).toContainText('You joined');await expect(client.page.locator('[data-puzzle-roster]')).toContainText(expectedActive+' / 6 active');await expect.poll(()=>Boolean(client.live?.roster?.selfParticipationId&&client.live.roster.memberIds.includes(client.selfId))).toBe(true);await verifyAuthority(client,'Explicit Join',await readDurable(client),{active:expectedActive,joined:true});return client.live.roster.selfParticipationId;}
