function pngInfo(bytes){assert.equal(bytes.toString('hex',0,8),'89504e470d0a1a0a');const width=bytes.readUInt32BE(16),height=bytes.readUInt32BE(20),depth=bytes[24],type=bytes[25];assert.equal(depth,8);assert.ok(type===2||type===6);const bpp=type===6?4:3,parts=[];let chunks=0;const crc32=data=>{let crc=0xffffffff;for(const byte of data){crc^=byte;for(let bit=0;bit<8;bit++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}return(crc^0xffffffff)>>>0;};for(let at=8;at<bytes.length;){const n=bytes.readUInt32BE(at),name=bytes.toString('ascii',at+4,at+8);assert.equal(crc32(bytes.subarray(at+4,at+8+n)),bytes.readUInt32BE(at+8+n),'Native PNG chunk CRC');if(name==='IDAT')parts.push(bytes.subarray(at+8,at+8+n));at+=n+12;chunks++;}const raw=inflateSync(Buffer.concat(parts)),stride=width*bpp,prior=Buffer.alloc(stride),row=Buffer.alloc(stride);let at=0,nonOpaque=0;const paeth=(a,b,c)=>{const p=a+b-c,pa=Math.abs(p-a),pb=Math.abs(p-b),pc=Math.abs(p-c);return pa<=pb&&pa<=pc?a:pb<=pc?b:c;};for(let y=0;y<height;y++){const filter=raw[at++];for(let x=0;x<stride;x++){const a=x>=bpp?row[x-bpp]:0,b=prior[x],c=x>=bpp?prior[x-bpp]:0,v=raw[at++];assert.ok(filter<=4);row[x]=(v+(filter===0?0:filter===1?a:filter===2?b:filter===3?Math.floor((a+b)/2):paeth(a,b,c)))&255;}if(bpp===4)for(let x=3;x<stride;x+=bpp)if(row[x]!==255)nonOpaque++;row.copy(prior);}assert.equal(nonOpaque,0,'Native capture opaque');return{width,height,nonOpaquePixels:nonOpaque,crcCheckedChunks:chunks};}
