async function bounded(promise,ms,name){let timer;try{return await Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(name+' timed out')),ms);})]);}finally{clearTimeout(timer);}}
async function cleanupOwnedResources(){
 const report={attempted:true,expectedContextCount:ownedContexts.length,contexts:[],errors:[],browserDisconnected:!browser,remainingContexts:0};
 await Promise.all(ownedContexts.map(async owned=>{const entry={client:owned.client,closeResolved:false,closeEvent:false,stillPresent:true};report.contexts.push(entry);try{await bounded(owned.context.close(),10000,'Owned context close');entry.closeResolved=true;}catch(error){report.errors.push({kind:'context-close',client:owned.client,message:error.message});}}));
 if(browser){try{await bounded(browser.close(),10000,'Owned browser close');}catch(error){report.errors.push({kind:'browser-close',message:error.message});}report.browserDisconnected=!browser.isConnected();report.remainingContexts=browser.contexts().length;}
 for(const entry of report.contexts){const owned=ownedContexts.find(item=>item.client===entry.client);entry.closeEvent=owned.closed;entry.stillPresent=Boolean(browser?.contexts().includes(owned.context));}
 return report;
}
